@@ -0,0 +1,21 @@
+import { log, flushLogs } from "./src/log.ts";
+import { handle } from "./src/handler.ts";
+
+async function testLogging() {
+  const start = Date.now();
+
+  // Simulate 100 requests, each with logging
+  for (let i = 0; i < 100; i++) {
+    handle(`/path${i}`);
+  }
+
+  const afterRequests = Date.now();
+  console.error(`[TEST] Handling 100 requests took ${afterRequests - start}ms (should be <10ms if truly non-blocking)`);
+
+  // Flush remaining logs
+  await flushLogs();
+  const afterFlush = Date.now();
+  console.error(`[TEST] Flushing logs took ${afterFlush - afterRequests}ms`);
+}
+
+testLogging().catch(console.error);
